Bash(node -e "
const fs = require\('fs'\);
let content = fs.readFileSync\('C:/projects/better-slides/components/editor/layout-canvas.tsx', 'utf8'\);

const startMarker = '\\t\\t\\t{/* \\u2500\\u2500 Canvas \(fills all remaining space\)';
const startIdx = content.indexOf\(startMarker\);

// End at the line '\\t\\t\\t</div>' just before '\\n\\t\\t</div>'
// That's the canvas wrapper closing div
const endMarker = '\\t\\t\\t</div>\\n\\t\\t</div>\\n\\t\);';
const endIdx = content.lastIndexOf\(endMarker\);

// We want to replace up to and including \\t\\t\\t</div>, keeping \\n\\t\\t</div>\\n\\t\); intact
const replaceEnd = endIdx + '\\t\\t\\t</div>'.length;

const toReplace = content.slice\(startIdx, replaceEnd\);
console.log\('Replacing', toReplace.length, 'chars'\);
console.log\('Last 100 of replacement target:', JSON.stringify\(toReplace.slice\(-100\)\)\);
")

